tool_and_message_events.command:
/bin/bash -lc "node --input-type=commonjs - <<'NODE'
const { spawnSync } = require('node:child_process');
for (const args of [
  ['--silent', 'start', '--', '5'],
  ['--silent', 'run', 'locate'],
  ['--silent', 'run', 'drain'],
]) {
  const result = spawnSync('npm', args, { encoding: 'utf8', timeout: 5000 });
  console.log(JSON.stringify({
    command: ['npm', ...args].join(' '),
    stdout: result.stdout,
    stderr: result.stderr,
    exit: result.status,
    signal: result.signal,
    error: result.error?.message
  }));
}
NODE"

